#define main original_hecbench_main
#include "../groupnorm-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <cmath>
#include <chrono>
int main(int argc,char**argv){
const int n=32768,C=32,G=8,B=4,img=256;std::string mode=argc>1?argv[1]:"forward";bool backward=mode=="backward";int repeats=backward?1:10;std::vector<float>hx(n),hw(C),hb(C),hdy(n),ho(n),hm(32),hr(32),hdx(n),hdw(C,0.f),hdb(C,0.f);for(int i=0;i<n;i++){hx[i]=float((i*13+(i/257)*7)%127-63)/64;hdy[i]=float((i*11+i/131)%31-15)/32;}for(int c=0;c<C;c++){hw[c]=.5f+float(c%7)/16;hb[c]=float((c*3)%9-4)/32;}std::vector<double>dw64(C,0),db64(C,0);for(int block=0;block<32;block++){int base=block*1024,wb=(block%8)*4;double sum=0,sum2=0;for(int i=0;i<1024;i++){double v=hx[base+i];sum+=v;sum2+=v*v;}double mu=sum/1024,rs=1/sqrt(sum2/1024-mu*mu+double(1e-5f));hm[block]=mu;hr[block]=rs;double first=0,second=0;for(int i=0;i<1024;i++){int c=wb+i/256;double norm=(hx[base+i]-mu)*rs;ho[base+i]=norm*hw[c]+hb[c];double wd=double(hw[c])*hdy[base+i];first+=wd;second+=wd*norm;dw64[c]+=double(hdy[base+i])*norm;db64[c]+=hdy[base+i];}for(int i=0;i<1024;i++){int c=wb+i/256;double norm=(hx[base+i]-mu)*rs;hdx[base+i]=(double(hw[c])*hdy[base+i]-first/1024-norm*second/1024)*rs;}}for(int c=0;c<C;c++){hdw[c]=dw64[c];hdb[c]=db64[c];}std::vector<float>expected;if(backward){expected.insert(expected.end(),hdx.begin(),hdx.end());expected.insert(expected.end(),hdw.begin(),hdw.end());expected.insert(expected.end(),hdb.begin(),hdb.end());}else{expected.insert(expected.end(),ho.begin(),ho.end());expected.insert(expected.end(),hm.begin(),hm.end());expected.insert(expected.end(),hr.begin(),hr.end());}float *x,*w,*b,*dy,*out,*mean,*rstd,*dx,*dw,*db;cudaMalloc(&x,n*4);cudaMalloc(&w,C*4);cudaMalloc(&b,C*4);cudaMalloc(&dy,n*4);cudaMalloc(&out,n*4);cudaMalloc(&mean,32*4);cudaMalloc(&rstd,32*4);cudaMalloc(&dx,n*4);cudaMalloc(&dw,C*4);cudaMalloc(&db,C*4);cudaMemcpy(x,hx.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(w,hw.data(),C*4,cudaMemcpyHostToDevice);cudaMemcpy(b,hb.data(),C*4,cudaMemcpyHostToDevice);cudaMemcpy(dy,hdy.data(),n*4,cudaMemcpyHostToDevice);cudaMemcpy(mean,hm.data(),128,cudaMemcpyHostToDevice);cudaMemcpy(rstd,hr.data(),128,cudaMemcpyHostToDevice);cudaMemset(dw,0,128);cudaMemset(db,0,128);
 auto launch=[&](){if(backward)groupnorm_backward(dy,x,mean,rstd,w,dx,dw,db,4,32,16,16,8);else if(mode=="forward2")groupnorm_forward2(x,w,b,out,mean,rstd,4,32,16,16,8);else groupnorm_forward(x,w,b,out,mean,rstd,4,32,16,16,8);};launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;
 bool allok=true;for(int trial=1;trial<=5;trial++){
 cudaMemset(dw,0,128);cudaMemset(db,0,128);cudaMemset(dx,0,n*4);cudaMemset(out,0,n*4);cudaMemcpy(mean,hm.data(),128,cudaMemcpyHostToDevice);cudaMemcpy(rstd,hr.data(),128,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeats;j++)launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeats;
 std::vector<float>got(32832);if(backward){cudaMemcpy(got.data(),dx,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n,dw,128,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n+32,db,128,cudaMemcpyDeviceToHost);}else{cudaMemcpy(got.data(),out,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n,mean,128,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n+32,rstd,128,cudaMemcpyDeviceToHost);}
 bool ok=status==cudaSuccess;double error=0,relative=0;for(size_t j=0;j<got.size();j++){double e=fabs((double)got[j]-expected[j]);error=fmax(error,e);relative=fmax(relative,e/fmax(fabs((double)expected[j]),0.001));ok&=std::isfinite((double)got[j])&&e<=0.001;}allok&=ok;
 char filename[80];snprintf(filename,sizeof(filename),"output_trial%d.bin",trial);FILE*f=fopen(filename,"wb");if(!f)return 5;fwrite(got.data(),sizeof(float),got.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),error,relative,repeats,filename,got.size());
 }return allok?0:1;
}
